-- ============================================================================
-- 0013 — roster snapshot and starting fives for the seeded season.
--
-- games.roster_snapshot exists so a later roster edit never rewrites a played
-- game's history, and games.starters is what derive() needs to know who was on
-- the floor at tip — without it every player's minutes, plus/minus and on-court
-- splits start from nothing and the box score is wrong in a way that looks
-- plausible.
--
-- The five lowest jerseys per side are the correct starters here because that
-- is literally what the scorer's showStarterPick() pre-selected when these
-- games were simulated through it.
--
-- Storing the snapshot also means the public game page needs one row rather
-- than a join across teams and roster_entries, so a finished box score renders
-- from a single request.
-- ============================================================================
update public.games set roster_snapshot = $s${"teams":[{"name":"neon city","color":"#93f2bf","players":[{"id":"59b6b9b4-e9d8-4db1-a7ee-eda4025b7ead","name":"marcus bell","num":"4"},{"id":"d5b6eb07-1ac0-465d-8432-73271603ed80","name":"toby ashworth","num":"5"},{"id":"f5741dec-dbc1-4006-8b35-72750128e86d","name":"devon clarke","num":"6"},{"id":"0649ac4b-a46f-4393-b218-ffd61ca21313","name":"isaac nwosu","num":"7"},{"id":"2a4014b6-cede-4fbd-b85f-a238748f7f6c","name":"rory mackenzie","num":"8"},{"id":"30d6740f-6090-4bf4-ab16-67c4b3af5147","name":"elliot sang","num":"9"},{"id":"437defa9-3106-49e8-b500-1d35c1f9b173","name":"callum reid","num":"10"},{"id":"c2efc9b9-6ff0-4f32-af84-a36317d8dec8","name":"jerome whitfield","num":"11"},{"id":"927cabd9-abbc-45fe-9f67-a081614f64aa","name":"danny okafor","num":"12"},{"id":"63d6753e-b2b0-4ae9-b1b8-b188865318ba","name":"kai brennan","num":"13"},{"id":"bc04a123-0def-4628-af80-609f5f298fae","name":"femi adeyemi","num":"14"},{"id":"36600a5f-be52-44e0-b26c-793e30cf70c2","name":"louis trent","num":"15"}]},{"name":"soft club","color":"#8ff5ff","players":[{"id":"487a0127-6049-4b15-8fe8-bd4bea10b62b","name":"andre fontaine","num":"4"},{"id":"d2be51f1-75dc-4383-8ab4-a16992501e18","name":"sam kowalski","num":"5"},{"id":"c6b3a181-a35f-4fc7-b449-8f470aa4249b","name":"tyrese boateng","num":"6"},{"id":"1ae55682-0fad-41cb-a811-d0f553a4830e","name":"nathan vasquez","num":"7"},{"id":"09f53d43-f0d5-4e66-a16f-c5ee5d36ea15","name":"owen hartley","num":"8"},{"id":"4fa1f67a-8651-4c9d-977d-8d57f66395a4","name":"malik osei","num":"9"},{"id":"88ac2af3-82c5-4ef1-9ff2-6331c3393b16","name":"jonah petrov","num":"10"},{"id":"2b32b0b9-2852-40de-b7f8-972f152fab5b","name":"reece sullivan","num":"11"},{"id":"bd562bfe-3f5e-4731-a427-81a116ee2e56","name":"dominic achebe","num":"12"},{"id":"9ee156b5-4caa-47a9-b4a9-9552cf8464d6","name":"finn gallagher","num":"13"},{"id":"32d68d9a-365b-48a6-8d7b-20310bf007c5","name":"xavier moreau","num":"14"},{"id":"8ceb9d3b-9b40-408c-99